items.syntax:
SHOW DATABASES;
SHOW SCHEMAS;
SHOW TABLES;

SELECT *
FROM sales
QUALIFY ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY sale_date DESC) = 1;

SELECT *
FROM monthly_sales
PIVOT (SUM(amount) FOR month IN ('Jan','Feb','Mar'));

SELECT *
FROM quarterly_totals
UNPIVOT (revenue FOR quarter IN (q1, q2, q3, q4));

-- Internal stage
CREATE STAGE my_stage;

-- External (S3)
CREATE STAGE s3_stage
  URL = 's3://my-bucket/data/'
  CREDENTIALS = (AWS_KEY_ID='...' AWS_SECRET_KEY='...');

COPY INTO @my_stage/export/
FROM my_table
FILE_FORMAT = (TYPE = 'PARQUET');

CREATE PIPE my_pipe AS
  COPY INTO my_table FROM @my_stage
  FILE_FORMAT = (TYPE = 'JSON');

CREATE TABLE events (
  id INT,
  payload VARIANT
);

SELECT f.value::STRING AS tag
FROM events,
LATERAL FLATTEN(INPUT => payload:tags) f;

-- By timestamp
SELECT * FROM orders
AT (TIMESTAMP => '2024-01-01 12:00:00'::TIMESTAMP);

-- By offset (seconds ago)
SELECT * FROM orders
BEFORE (OFFSET => -3600);

UNDROP TABLE orders;
UNDROP SCHEMA my_schema;
UNDROP DATABASE my_db;

CREATE TABLE orders_jan
  CLONE orders
  BEFORE (TIMESTAMP => '2024-02-01'::TIMESTAMP);

CREATE ROW ACCESS POLICY region_policy AS
  (region STRING) RETURNS BOOLEAN ->
  region = CURRENT_ROLE();

ALTER TABLE sales ADD ROW ACCESS POLICY region_policy ON (region);

CREATE MATERIALIZED VIEW mv_daily_sales AS
  SELECT date, SUM(amount) AS total
  FROM orders GROUP BY date;
